"""Reviewed exact commerce stock operations; reservation ports are local application contracts."""
def extend(spec):
    from authorization import object_schema, parameter, operation, REF, UUID, VERSION
    s=spec['components']['schemas']
    quantity={'type':'string','pattern':r'^(0|[1-9][0-9]{0,16})(\.[0-9]{1,3})?$','description':'Decimal string, canonical output at immutable SKU quantity scale0..3; never JSON float.'}
    s['StockDTO']=object_schema({'skuId':UUID,'locationId':UUID,'onHand':quantity,'reserved':quantity,'allocated':quantity,'available':quantity,'version':VERSION})
    s['StockPage']=object_schema({'items':{'type':'array','maxItems':100,'items':REF('StockDTO')},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'totalElements':VERSION,'totalPages':VERSION})
    location=object_schema({'code':{'type':'string','pattern':'^[A-Z0-9][A-Z0-9_-]{0,39}$'},'name':{'type':'string','minLength':1,'maxLength':120}});s['NewStockLocation']=location;s['StockLocation']=object_schema({'id':UUID,**location['properties'],'active':{'type':'boolean'},'version':VERSION})
    s['StockAdjustment']=object_schema({'skuId':UUID,'locationId':UUID,'delta':{'type':'string','pattern':r'^-?(0|[1-9][0-9]{0,16})(\.[0-9]{1,3})?$','description':'Nonzero signed decimal; quantity scale must fit the SKU, numeric20,3 range. No exponent/plus/whitespace or floating-point JSON.'},'reason':{'type':'string','minLength':10,'maxLength':500,'description':'At least10 nonpadding characters, no control/format characters; retained in owned immutable movement, redacted from public DTO/audit.'}})
    read=operation('API-045','Current OPERATIONS, no organization. Owned balance/immutable SKU scale only; bounded fixed sorting and stable UUID tie-breaker. Repeatable-read page/count snapshot, no-store. Counts are not reservation authority. Unknown/duplicate queries and any body rejected.','StockPage',[parameter('skuId','query',UUID),parameter('locationId','query',UUID),parameter('page','query',{'type':'integer','minimum':0,'default':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100,'default':20}),parameter('sort','query',{'type':'string','enum':['skuId,asc','skuId,desc','locationId,asc','locationId,desc','available,asc','available,desc'],'default':'skuId,asc'})])
    headers=[parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True),parameter('X-CSRF-TOKEN','header',{'type':'string','minLength':43,'maxLength':43},True)]
    create=operation('API-170','Current OPERATIONS and session CSRF. Explicit unique location code/name, active=true/version0. Creation inserts no inventory balance and no available stock; actual locations and fulfillment priority are approved configuration, never guessed. Atomic redacted audit and durable response.','StockLocation',headers)
    adjust=operation('API-046','Current OPERATIONS and session CSRF/quoted If-Match; ADMIN has no implicit stock permission. Absent SKU/location balance starts at zero/version0 only inside this explicit adjustment. Lock current Party, active location/SKU and balance; enforce SKU scale, reserved+allocated floor and numeric upper bound. Atomic append-only movement with stable actor/API/key business identity, balance revision, redacted audit, EVT-005 and durable response. Same command cannot double-adjust; cached replay requires current authority. Failed movement/audit/outbox leaves no stock effect. Actual stock must be physically verified.','StockDTO',[*headers,parameter('If-Match','header',{'type':'string','pattern':'^"(0|[1-9][0-9]{0,18})"$'},True)])
    for op,name in ((create,'NewStockLocation'),(adjust,'StockAdjustment')):
        op['requestBody']={'required':True,'content':{'application/json':{'schema':REF(name)}}};op['responses']['201']=op['responses'].pop('200');op['responses']['201']['headers']={'ETag':{'schema':{'type':'string'}},'Cache-Control':{'schema':{'const':'no-store'}}}
    read['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}}
    for op in (read,create,adjust):op['responses']['422']['description']='Inventory rule violation; no negative available stock or quantity overflow'
    spec['paths']['/api/v1/staff/inventory']={'get':read};spec['paths']['/api/v1/staff/stock-adjustments']={'post':adjust};spec['paths']['/api/v1/staff/stock-locations']={'post':create};return spec
